def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    out = [[bg for _ in range(w)] for _ in range(h)]
    seen = [[False] * w for _ in range(h)]
    boxes = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r,c)])
            seen[r][c] = True
            cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx]=True; q.append((ny,nx))
            if len(cells) >= 3:
                r0=min(y for y,x in cells); r1=max(y for y,x in cells)
                c0=min(x for y,x in cells); c1=max(x for y,x in cells)
                # A zero marker just outside the lower-left edge can mark an omitted last row.
                if r1 + 1 < h and c0 > 0 and grid[r1+1][c0-1] == 0:
